<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { BarChart3, CheckCircle2, Database, Plus, RefreshCw, ShieldCheck } from 'lucide-vue-next'
import { api, date, hasRole, post } from './api'
const datasets=ref<any[]>([]),evaluations=ref<any[]>([]),thresholds=ref<any[]>([]),policies=ref<any[]>([]),busy=ref(false),thresholdOpen=ref(false)
const form=ref<any>({name:'手机审核分流',evaluation_id:'',calibration_method:'platt',thresholds:{confirm_min:.98,review_min:.65,margin_min:.08}})
async function load(){busy.value=true;try{const [d,e,t,p]=await Promise.all([api('/datasets'),api('/evaluations'),api('/threshold-policies'),api('/policies')]);datasets.value=d.items;evaluations.value=e.items;thresholds.value=t.items;policies.value=p.items}finally{busy.value=false}}
function pct(v:any){return typeof v==='number'?(v*100).toFixed(1)+'%':'—'}
function scope(v:string){return {simulation:'构造数据',public:'公开数据',authorized:'授权业务数据'}[v]||v}
async function create(){try{await post('/threshold-policies',form.value);thresholdOpen.value=false;await load();ElMessage.success('阈值策略草稿已创建')}catch(e:any){ElMessage.error(e.message)} }
async function approve(row:any){try{const {value}=await ElMessageBox.prompt('审批只影响之后创建的运行，历史结果保持原模型和阈值。','审批阈值策略',{inputPlaceholder:'填写审批依据',inputValidator:v=>!!v?.trim()||'请填写依据'});const base=policies.value[0];await post(`/threshold-policies/${row.id}/approve`,{reason:value,base_policy_id:base.id,activate_default:false});await load();ElMessage.success('已生成新的匹配方案版本')}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div class="v14-page"><div class="page-heading"><div><div class="heading-kicker">冻结基准与模型准入</div><h1>算法评测</h1><p>按数据范围展示检索、排序、校准和拒识结果。</p></div><div class="button-row"><el-button @click="load"><RefreshCw :size="15"/>刷新</el-button><el-button v-if="hasRole('admin')&&evaluations.length" type="primary" @click="form.evaluation_id=evaluations[0].id;thresholdOpen=true"><Plus :size="15"/>阈值策略</el-button></div></div><el-alert title="构造数据只用于工程正确性和相对对比，不能代表企业真实准确率或人工节时。" type="info" :closable="false"/><div class="algorithm-layout" v-loading="busy"><section class="panel"><div class="panel-header"><div><h3>冻结评测运行</h3><p class="muted">每个指标绑定数据集、样本量和内容摘要。</p></div></div><article v-for="e in evaluations" class="evaluation-row"><div class="evaluation-head"><div><span class="scope-label" :class="e.scope">{{ scope(e.scope) }}</span><strong>{{ e.name }}</strong><small>{{ e.baseline_name }} · {{ date(e.created_at) }} · n={{ e.metrics.sample_size }}</small></div><span class="status-pill SUCCEEDED"><CheckCircle2 :size="12"/>已冻结</span></div><div class="metric-strip"><div><span>Recall@20</span><strong>{{ pct(e.metrics.recall_at_20) }}</strong></div><div><span>Top 1</span><strong>{{ pct(e.metrics.top1) }}</strong></div><div><span>nDCG@5</span><strong>{{ pct(e.metrics.ndcg_at_5) }}</strong></div><div><span>建议区精确率</span><strong>{{ pct(e.metrics.suggestion_precision) }}</strong><small>95% 下限 {{ pct(e.metrics.suggestion_precision_ci_lower) }}</small></div><div><span>校准 ECE</span><strong>{{ e.metrics.ece?.toFixed(4) }}</strong></div><div><span>拒识率</span><strong>{{ pct(e.metrics.rejection_rate) }}</strong></div><div><span>推理 P95</span><strong>{{ e.metrics.inference_p95_ms?.toFixed(2) }} ms</strong></div></div><details class="evaluation-details"><summary>查看评测范围与摘要</summary><dl class="spec-list"><dt>数据范围</dt><dd>{{ scope(e.scope) }}</dd><dt>内容摘要</dt><dd class="mono wrap">{{ e.content_hash }}</dd><dt>硬冲突进入建议区</dt><dd>{{ e.metrics.hard_conflict_suggestions }} 条</dd><dt>建议覆盖</dt><dd>{{ pct(e.metrics.suggestion_coverage) }}</dd></dl></details></article><el-empty v-if="!evaluations.length" description="尚未登记冻结评测运行"/></section><aside class="panel algorithm-side"><div class="section-title"><h3>数据集清单</h3><Database :size="17"/></div><div v-for="d in datasets" class="dataset-line"><strong>{{ d.name }}</strong><span>{{ scope(d.provenance.source_type) }} · {{ d.status==='FROZEN'?'已冻结':'准备中' }}</span><small class="mono">{{ d.content_hash?.slice(0,16)||'尚无摘要' }}</small></div><div class="section-title mt16"><h3>阈值策略</h3><ShieldCheck :size="17"/></div><div v-for="t in thresholds" class="threshold-line"><div><strong>{{ t.name }} v{{ t.number }}</strong><span>{{ t.calibration_method }} · 建议确认 ≥ {{ t.thresholds.confirm_min }}</span></div><span class="status-pill" :class="t.status==='APPROVED'?'SUCCEEDED':'QUEUED'">{{ {DRAFT:'待审批',APPROVED:'已批准',RETIRED:'历史版本'}[t.status as 'DRAFT'] }}</span><button v-if="t.status==='DRAFT'&&hasRole('admin')" class="text-button" @click="approve(t)">审批</button></div></aside></div><el-dialog v-model="thresholdOpen" title="创建阈值策略" width="570px"><label>策略名称</label><el-input v-model="form.name"/><label>冻结评测</label><el-select v-model="form.evaluation_id" class="full"><el-option v-for="e in evaluations" :value="e.id" :label="`${e.name} · ${scope(e.scope)}`"/></el-select><label>校准方式</label><el-segmented v-model="form.calibration_method" :options="[{label:'Platt Scaling',value:'platt'},{label:'Isotonic',value:'isotonic'}]"/><div class="form-columns"><div><label>建议确认下限</label><el-input-number v-model="form.thresholds.confirm_min" :min="0" :max="1" :step=".01"/></div><div><label>重点复核下限</label><el-input-number v-model="form.thresholds.review_min" :min="0" :max="1" :step=".01"/></div><div><label>前两名最小分差</label><el-input-number v-model="form.thresholds.margin_min" :min="0" :max="1" :step=".01"/></div></div><template #footer><el-button @click="thresholdOpen=false">取消</el-button><el-button type="primary" @click="create">保存草稿</el-button></template></el-dialog></div></template>
